import {museumLink,museumHost,DEFAULT_MUSEUM_HOST} from './museum-link.js';
import {createOfflineLibrary} from './offline.js';
import {glossedText,wordTokens,validGlosses,installWordGlosses} from './glosses.js';
import {createMuseumQuiz,museumSelections} from './museum.js';
import {validateCourse, freshProgress, safeProgress, normalize, accepts, shuffle, localDay, streak, finishSession, cardKey, forkCourse} from './lib.js';
import {createSpeechPlayer,isReviewedAudio,isPlayableAudio} from './speech.js';
import {CEFR_LEVELS,CEFR_SOURCE,courseLevels,levelIndex,lessonQueue,SCHOOL_SOURCE,schoolLessons,schoolStages} from './curriculum.js';
const $ = (s) => document.querySelector(s);
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const REPO = 'https://github.com/smichea/tara';
const KEY = 'tara-progress-v1', CUSTOM = 'tara-courses-v1', DRAFT = 'tara-draft-v1';
const icons={learn:'<path d="m3 5 9-3 9 3v14l-9 3-9-3zM12 2v20M3 5l9 3 9-3"/>',review:'<path d="M3 11a9 9 0 1 1 2 7M3 4v7h7"/>',words:'<rect x="4" y="3" width="16" height="18" rx="3"/><path d="M8 8h8M8 12h8M8 16h5"/>',community:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-4a6 6 0 0 1 12 0v4M16 4a3 3 0 0 1 0 6M17 13a5 5 0 0 1 4 5v3"/>',settings:'<circle cx="12" cy="12" r="3"/><path d="m9 3-1 3-3 1-2 4 2 3v4l4 3 3-1 3 1 4-3v-4l2-3-2-4-3-1-1-3z"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',sound:'<path d="m11 4-6 5H2v6h3l6 5zM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14"/>',flame:'<path d="M13 2c2 8-6 7-3 13 2-1 3-3 4-5 8 7 5 12-2 12C1 22 1 10 7 7c0 4 2 4 2 4 3-3 4-5 4-9z"/>',star:'<path d="m12 2 3 6 7 1-5 5 1 8-6-4-6 4 1-8-5-5 7-1z"/>',code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18"/>',plus:'<path d="M12 4v16M4 12h16"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',globe:'<circle cx="12" cy="12" r="10"/><ellipse cx="12" cy="12" rx="4" ry="10"/><path d="M2 12h20"/>'};
const icon = (id) => `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${icons[id]||(id==='school'?icons.learn:icons.star)}</svg>`;
let courses=[], custom=[], course, progress=freshProgress(), session=null, result=null, route='learn', draft=null, storageFailed=false;
let toastTimer, draftLessonIndex=0;
const offlineLibrary=createOfflineLibrary();
let installPrompt=null,installed=window.matchMedia('(display-mode: standalone)').matches||navigator.standalone===true;
let downloads=new Map(),downloadJob=null,downloadSearch='',downloadLevel='all',workerReady=false,workerFailed=false;
window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();installPrompt=event;if(!session&&['settings','downloads'].includes(route))render();});
window.addEventListener('appinstalled',()=>{installed=true;installPrompt=null;if(!session&&['settings','downloads'].includes(route))render();});
window.addEventListener('online',()=>{if(route==='downloads')renderDownloadList();});
window.addEventListener('offline',()=>{if(route==='downloads')renderDownloadList();});
const wordGlosses=installWordGlosses();
const speech = createSpeechPlayer(window, {onError:speechError,getVoiceApprovals:()=>course?.audioVoiceApprovals||[]});
function read(key,fallback){try{const raw=localStorage.getItem(key);return raw?JSON.parse(raw):fallback;}catch{return fallback;}}
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{storageFailed=true;toast('Storage is unavailable. Export a backup to keep your work.');return false;}}
function progressKey(){return course?.learnerId?`${KEY}:${course.learnerId}`:KEY;}
function loadProgress(){try{progress=safeProgress(read(progressKey(),freshProgress()));}catch{progress=freshProgress();storageFailed=true;}}
function save(){return persist(progressKey(),progress);}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4500);}
function confirmAction(title,message,action){const d=$('#dialog');d.innerHTML=`<h2>${esc(title)}</h2><p>${esc(message)}</p><form method="dialog" class="actions"><button class="btn secondary" value="cancel">Cancel</button><button class="btn" value="confirm">Continue</button></form>`;d.showModal();d.onclose=()=>{if(d.returnValue==='confirm')action();};}
function allEntries(){return course.lessons.flatMap(l=>l.entries.map(e=>({...e,lessonTitle:l.title,level:l.level})));}
function learned(){return allEntries().filter(e=>progress.cards[cardKey(course,e)]);}
function due(){return learned().filter(e=>progress.cards[cardKey(course,e)].due<=Date.now());}
function completed(l){return !!progress.lessons[`${course.id}:${l.id}`];}
function activeLevel(){const saved=read(`tara-level-${course.id}`,null),levels=courseLevels(course);return saved==='all'||levels.some(l=>l.id===saved)?saved:levels[0]?.id||'all';}
function visibleLessons(){const level=activeLevel();return course.lessons.filter(l=>level==='all'||l.level===level);}
function nextLesson(){const lessons=visibleLessons();return lessons.find(l=>!completed(l))||lessons[0]||course.lessons[0];}
function levelPicker(){const levels=courseLevels(course);if(!levels.length)return '';const current=activeLevel(),info=CEFR_LEVELS.find(l=>l.id===current);return `<section class="level-panel"><div class="level-tabs" aria-label="Choose a practice level">${[{id:'all',title:'All levels'},...levels].map(l=>`<button class="level-tab" data-action="level" data-id="${l.id}" aria-pressed="${current===l.id}">${l.id==='all'?'All':l.id}</button>`).join('')}</div><p><strong>${info?`${info.id} · ${info.title}`:'From first words to nuanced expression'}</strong><br>${esc(info?.description||'Choose a level to see its learning goals and lessons.')}</p><p class="tiny">CEFR-inspired practice targets. Completing lessons does not certify a CEFR level. <a href="${CEFR_SOURCE}" target="_blank" rel="noopener">About the framework</a></p></section>`;}
function learningPath(next){let previous;return visibleLessons().map((l,i)=>{const heading=l.level!==previous;previous=l.level;return `${heading&&l.level?`<div class="unit-heading"><span>${esc(l.level)}</span><h3>${esc(CEFR_LEVELS.find(x=>x.id===l.level)?.title||'Keep exploring')}</h3></div>`:''}<button class="lesson ${completed(l)?'done':next.id===l.id?'current':''}" data-action="start" data-id="${esc(l.id)}"><span class="lesson-number">${completed(l)?icon('check'):String(course.lessons.indexOf(l)+1).padStart(2,'0')}</span><span class="lesson-text"><h3>${esc(l.title)}</h3><p>${esc(l.goal)}</p>${l.reading?'<span class="tiny">Phrases · reading · comprehension · expression</span>':''}</span>${icon('arrow')}</button>`;}).join('');}
function nextRoute(r){if(session){confirmAction('Leave this lesson?','Your completed lessons are saved. This unfinished session will be lost.',()=>{session=null;result=null;location.hash=r;render();});return;}location.hash=r;if(route===r)render();}
function speechError(error){toast(error==='unreviewed'?'A fluent reviewer has not approved a recording for this text yet.':'This recording could not be played. Try again when connected.');}
function speak(entry,rate=1){speech.speak(entry,course.languageCode,rate);}
function canSpeak(entry){return speech.supported&&isPlayableAudio(entry,course.audioVoiceApprovals);}
function audioButton(entry,slow=false){return `<button class="${slow?'btn ghost small':'audio-btn'}" data-action="audio" data-rate="${slow?'.8':'1'}" data-id="${esc(entry.id)}" aria-label="${slow?'Listen slowly to':'Listen to'} ${esc(entry.text)}" ${canSpeak(entry)?'':`disabled title="${entry.audio?'Recording awaiting fluent-speaker approval':'No recording for this phrase yet'}"`}>${icon('sound')}${slow?'Slower':''}</button>`;}
function audioControls(entry){return `<div class="actions speech-controls">${audioButton(entry)}${audioButton(entry,true)}${canSpeak(entry)?'':`<span class="tiny">${entry.audio?'Recording awaiting review':'Audio not available yet'}</span>`}</div>`;}
function speechHelp(){const count=allEntries().filter(e=>isPlayableAudio(e,course.audioVoiceApprovals)).length;return count?`${count} stored phrase recordings. Voice: Marin. ${course.languageCode==='fr'?'Synthetic French recordings; individual pronunciation feedback is welcome.':'Chosen after listening to 12 Filipino sample recordings.'} Tap a speaker to listen, or Slower to practise.`:'Recordings are being prepared. Sound becomes available phrase by phrase after pronunciation approval for the recording or its voice pilot.';}
function illustration(){if(course.languageCode==='fr')return `<svg class="hero-art" viewBox="0 0 330 270" preserveAspectRatio="xMidYMax slice" aria-hidden="true"><circle cx="244" cy="67" r="42" fill="#e9cf72"/><path d="M0 239q105-35 194 2t150-4v33H0" fill="#8eaa67"/><g fill="#296c4d"><path d="M18 228v-69h58v69M88 228v-92h56v92M244 228v-75h65v75"/><path d="m13 159 34-22 34 22m2-23 33-23 33 23m91 17 36-24 36 24"/></g><g stroke="#c9dfa7" stroke-width="9" fill="none" stroke-linejoin="round"><path d="m151 236 22-59 16-69 8-67 9 67 16 69 24 59M168 187h59M178 139h39M188 104h20M197 28v14"/><path d="M171 236q27-55 54 0"/></g><path d="M9 255q71-18 140-2t166-1" stroke="#e9cf72" stroke-width="4" fill="none"/><g fill="#e9cf72"><path d="m96 68 3-9 3 9 9 3-9 3-3 9-3-9-9-3z"/><circle cx="288" cy="112" r="3"/></g></svg>`;return `<svg class="hero-art" viewBox="0 0 330 270" preserveAspectRatio="xMidYMax slice" aria-hidden="true"><circle cx="223" cy="84" r="44" fill="#e9cf72"/><path d="M-20 255 105 98 240 270" fill="#296c4d"/><path d="m70 270 151-146 150 146" fill="#43825a"/><path d="m130 270 130-93 120 93" fill="#8eaa67"/><path d="M176 256q8-65 0-139" stroke="#d1b66c" stroke-width="7" fill="none"/><g fill="#b2cb7b"><path d="M179 120q-48-62-89-21 50-8 89 21"/><path d="M178 120q-11-76 33-82-22 34-33 82"/><path d="M180 121q44-53 88-15-49-4-88 15"/><path d="M179 119q29-18 60 21-36-9-60-21"/><path d="M178 120q-42-21-62 20 30-15 62-20"/></g><path d="M3 264q100-39 210 0" stroke="#d0d99a" stroke-width="4" fill="none"/><g fill="#e9cf72"><path d="m72 57 2-8 3 8 8 2-8 3-3 8-2-8-8-3z"/><circle cx="291" cy="50" r="3"/><circle cx="100" cy="35" r="2"/></g></svg>`;}
function shell(body){
 const nav=[['learn','Learn'],['school','School path'],['review','Review'],['words','Phrasebook'],['community','Community'],['settings','Settings']];
 return `<div class="shell"><aside class="sidebar"><a class="brand" href="#learn" aria-label="Tara home">tara<span>!</span></a><p class="brand-caption">Language. Together.</p><nav class="nav" aria-label="Main navigation">${nav.map(([id,title])=>`<a href="#${id}" ${route===id?'class="active" aria-current="page"':''}>${icon(id)}${title}</a>`).join('')}</nav><div class="side-bottom"><a class="open-badge" href="${REPO}" target="_blank" rel="noopener">${icon('code')} Open source. Open to you.</a><p>Built by people.<br>For real conversations.<br>Free, without the ads.</p></div></aside><div class="workspace"><header class="topbar"><div class="actions"><span class="brand mobile-brand">t<span>!</span></span><label class="sr-only" for="course-select">Choose a language course</label><select id="course-select" class="course-select">${[...courses,...custom].map(c=>`<option value="${esc(c.id)}" ${c.id===course.id?'selected':''}>${esc(c.language)} - from ${esc(c.fromLanguage)}${custom.includes(c)?' (local)':''}</option>`).join('')}</select></div><div class="stats"><span class="stat" title="Days in a row">${icon('flame')}${streak(progress.activity)} <span class="desktop-label">day${streak(progress.activity)===1?'':'s'}</span></span><span class="stat">${icon('star')}${progress.xp} XP</span><span class="avatar" title="${esc(course.learnerName||'Your learning')}, on this device">${esc((course.learnerName||'Marco').slice(0,1))}</span></div></header><main id="main" class="content" tabindex="-1">${storageFailed?'<div class="warning">Browser storage is unavailable. Export your progress before closing this page.</div>':''}${body}</main></div></div>`;
}
function intro(eyebrow,title,text,right=''){return `<div class="page-intro"><div><p class="eyebrow">${eyebrow}</p><h1>${title}</h1><p>${text}</p></div>${right}</div>`;}
function home(){
 const next=nextLesson(), count=course.lessons.filter(completed).length, goal=!!progress.activity[localDay()];
 const shown=visibleLessons(),shownDone=shown.filter(completed).length;
 return intro(course.learnerName?`For ${esc(course.learnerName)} · A little every day`:'A little every day','Your next conversation starts here.',`A few minutes of ${esc(course.language)}. A little more confidence.`,`<span class="pill green">${icon('globe')} ${esc(course.fromLanguage)} → ${esc(course.language)}</span>`)+
 `${schoolStages(course).length?`<a class="school-invitation" href="#school"><span class="pill green">Foundations → Grade 8</span><span>Build the earlier-grade skills, then work toward your class texts.</span>${icon('arrow')}</a>`:''}${levelPicker()}<section class="hero"><div class="hero-copy"><p class="eyebrow">${shownDone===shown.length?'Keep your momentum':'Your next small step'}</p><h2>${esc(next.title)}<br><span style="color:#c9dfa7">You’ve got this.</span></h2><p>${esc(next.goal)}</p><button class="btn lime" data-action="start" data-id="${esc(next.id)}">${shownDone===shown.length?'Practise again':'Let’s do this'} ${icon('arrow')}</button></div>${illustration()}</section><div class="dashboard"><section aria-label="Lesson path"><div class="section-head"><h2>Your learning path</h2><a class="text-link" href="#downloads">${icon('download')} Downloads</a><span class="tiny">${shownDone} / ${shown.length} complete · ${activeLevel()==='all'?'all levels':activeLevel()}</span></div><div class="lessons">${learningPath(next)}</div><p class="footer-note">Every lesson is available. No hearts, no waiting.<br>${course.status==='draft'?'These lessons are drafts awaiting fluent-speaker and teacher review.':''}</p></section><aside class="dashboard-aside"><section class="side-card"><h3>A small daily win</h3><div class="goal-ring-row"><div class="goal-ring ${goal?'done':''}">${goal?icon('check'):'0/1'}</div><div><strong>${goal?'You showed up!':'One short session'}</strong><p>${goal?'Your daily goal is complete.':'That’s all it takes to start.'}</p></div></div><div class="week">${Array.from({length:7},(_,i)=>{const d=new Date();d.setDate(d.getDate()-6+i);return `<div class="day">${d.toLocaleDateString('en',{weekday:'narrow'})}<i class="${progress.activity[localDay(d)]?'on':''}">${progress.activity[localDay(d)]?'✓':'·'}</i></div>`;}).join('')}</div></section><section class="side-card warm"><div class="real-world">↗</div><h3>Take it into the real world</h3><p>Try one new phrase with a friend today. It doesn’t have to be perfect.</p><span class="pill">Small steps count.</span></section><section class="side-card"><h3>Better with company.</h3><p>Try ${esc(course.language)} questions together with Retro Museum’s multiplayer quiz.</p><a href="#play" class="text-link">Play together ${icon('arrow')}</a></section><section class="side-card"><h3>A language belongs to everyone.</h3><p>Know a better way to say it? Help the next learner find their words.</p><a href="#community" class="text-link">Meet the community ${icon('arrow')}</a></section></aside></div>`;
}
async function openMuseum(selection){
 const status=$('#museum-launch-status'),button=$('[data-action="play-museum"]');let target;
 try{target=museumHost($('#museum-host')?.value||DEFAULT_MUSEUM_HOST);}catch(error){toast(error.message);return;}
 if(!navigator.onLine&&target===DEFAULT_MUSEUM_HOST){toast('Reconnect to create an online room. Downloaded Tara lessons remain available offline.');return;}
 const popup=window.open('about:blank','_blank');if(popup)popup.opener=null;
 if(button)button.disabled=true;if(status)status.textContent='Preparing your quiz…';
 try{
  const url=await museumLink(course,selection,target);persist('tara-museum-host',target);
  if(popup&&!popup.closed){popup.location.replace(url);if(status)status.textContent='Your quiz is open in Retro Museum. Create the room there, then invite everyone.';}
  else if(status){status.replaceChildren();const link=document.createElement('a');link.href=url;link.target='_blank';link.rel='noopener noreferrer';link.className='text-link';link.textContent='Open your quiz in Retro Museum →';status.append(link);}
 }catch(error){popup?.close();if(status)status.textContent=error.message;toast(error.message||'Could not prepare this quiz.');}
 finally{if(button)button.disabled=false;}
}
function playPage(){const selections=museumSelections(course),saved=read(`tara-quiz-${course.id}`,'school-foundations'),chosen=selections.find(x=>x.id===saved)||selections[0];let bank;try{bank=createMuseumQuiz(course,chosen.id);}catch{return intro('Play together','Add a few more distinct phrases.','This course needs enough different meanings for a four-choice quiz. Add them in Community, then return here.');}return intro('Language, together','Make it a shared challenge.','Choose a practice pack for Retro Museum. Open a room on a shared screen; everyone joins with a phone.')+`<section class="hero"><div class="hero-copy"><p class="eyebrow">A little friendly competition</p><h2>Same room.<br><span style="color:#c9dfa7">More voices.</span></h2><p>Ranking, cooperative play and a reveal after each question. Take time to discuss the phrases together.</p></div>${illustration()}</section><div class="grid"><section class="card"><h2>Choose your practice</h2><label for="quiz-selection">Question pack</label><select id="quiz-selection" class="field">${selections.map(x=>`<option value="${x.id}" ${chosen.id===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select><p>${bank.questions.length} distinct phrase questions · four choices each · English instructions.</p><div class="actions"><button class="btn secondary" data-action="export-quiz" data-id="${chosen.id}">Download questions ${icon('download')}</button>${course.id==='fil-en'&&!custom.includes(course)?`<a class="btn secondary" href="museum/${chosen.id}.rmg.json" download="tara-${chosen.id}.rmg.json">Download game pack ${icon('download')}</a>`:''}</div><p class="tiny">The questions carry the course’s draft status and CC BY-SA 4.0 attribution. Game packs contain up to 100 questions; the question download keeps the full bank. Quiz scores do not change your individual learning progress.</p></section><section class="card"><h2>Play in Retro Museum</h2><p>Open your selected quiz directly. Choose the rules, create a room, then invite everyone with its QR code. No files to move.</p><div class="actions"><button class="btn" data-action="play-museum" data-id="${chosen.id}">Play in Retro Museum ${icon('arrow')}</button><a class="text-link" href="${REPO}/blob/main/docs/multiplayer.md" target="_blank" rel="noopener">Host setup</a></div><p id="museum-launch-status" role="status" class="tiny"></p><details class="install-help"><summary>Use your own museum host</summary><label for="museum-host">Retro Museum address</label><input id="museum-host" type="url" value="${esc(read('tara-museum-host',DEFAULT_MUSEUM_HOST))}" placeholder="http://192.168.1.20:4310/play/"><p class="field-help">Use a museum with Tara quiz support. Leave the default address for Manaty Play.</p></details><p class="tiny">Only the selected questions and their attribution are sent. Your learning progress stays in Tara. The quiz is used in your room, without submission to the public catalog. Use a nickname when joining. Creating an online room needs a connection.</p></section></div><a class="text-link" href="#school" style="display:inline-flex;margin-top:24px">Back to the school pathway ${icon('arrow')}</a>`;}

function schoolPage(){
 const stages=schoolStages(course);if(!stages.length)return intro('School path','Make room for another pathway.','This course has no school mapping yet. Contributors can add sourced grade and quarter references in the editor.');
 const saved=read(`tara-school-${course.id}`,null),stage=stages.find(s=>s.id===saved)||stages[0],lessons=schoolLessons(course,stage.id),done=lessons.filter(completed).length,next=lessons.find(l=>!completed(l))||lessons[0],previous=stages[stages.indexOf(stage)-1];
 return intro('One step at a time','From first words to Grade 8.','Build the missing foundations, revisit an earlier grade, then apply the skills to your school texts.')+`<section class="school-overview"><div class="section-head"><h2>Your school pathway</h2><span class="pill green">Every stage is open</span></div><div class="school-stages" aria-label="Choose a school stage">${stages.map((s,i)=>{const items=schoolLessons(course,s.id),n=items.filter(completed).length;return `<button class="school-stage ${s.id===stage.id?'selected':''}" data-action="school-stage" data-id="${s.id}" aria-pressed="${s.id===stage.id}"><span class="stage-step">${i+1}</span><strong>${esc(s.title)}</strong><span>${esc(s.caption)}</span><span class="stage-count">${n} / ${items.length} lessons</span><span class="stage-meter" aria-hidden="true"><i style="width:${100*n/items.length}%"></i></span></button>`;}).join('')}</div><p class="tiny">Foundation practice prepares early literacy; it is not an official Grade 1 Filipino syllabus. Grades 2–8 reference the <a href="${SCHOOL_SOURCE}" target="_blank" rel="noopener">DepEd MATATAG Filipino guide</a>. Mappings and lessons await teacher and fluent-speaker review.</p></section><section class="hero school-hero"><div class="hero-copy"><p class="eyebrow">${esc(stage.caption)}</p><h2>${esc(stage.title)}<br><span style="color:#c9dfa7">Build on what you know.</span></h2><p>${esc(stage.description)}</p><button class="btn lime" data-action="start" data-id="${esc(next.id)}">${done===lessons.length?'Practise again':'Continue this stage'} ${icon('arrow')}</button></div>${illustration()}</section><div class="dashboard"><section id="school-lessons"><div class="section-head"><h2>${esc(stage.title)} practice</h2><span class="tiny">${done} / ${lessons.length} complete</span></div>${[...(stage.id==='foundations'?[0]:[1,2,3,4])].map(q=>{const group=lessons.filter(l=>!q||l.school?.quarter===q);return group.length?`<div class="unit-heading"><span>${q?'Q'+q:'Start'}</span><h3>${q?'Quarter '+q:'First building blocks'}</h3></div><div class="lessons">${group.map(l=>`<button class="lesson ${completed(l)?'done':next.id===l.id?'current':''}" data-action="start" data-id="${esc(l.id)}"><span class="lesson-number">${completed(l)?icon('check'):String(lessons.indexOf(l)+1).padStart(2,'0')}</span><span class="lesson-text"><h3>${esc(l.title.replace(/^(G\d+ Q\d|Foundations) · /,''))}</h3><p>${esc(l.goal)}</p><span class="tiny">Read · understand · write</span></span>${icon('arrow')}</button>`).join('')}</div>`:'';}).join('')}</section><aside class="dashboard-aside"><section class="side-card warm"><p class="eyebrow">Before moving on</p><h3>Try it with a new text.</h3><p>${esc(stage.check)}</p><p class="tiny">Lesson completion records practice. A teacher or fluent listener should check independent reading, writing and speaking.</p></section>${previous?`<section class="side-card"><h3>Need a building block?</h3><p>Earlier stages stay available. Return to ${esc(previous.title)} whenever a task feels too difficult.</p><button class="btn secondary small" data-action="school-stage" data-id="${previous.id}">Revisit ${esc(previous.title)}</button></section>`:''}<section class="side-card"><h3>Your actual class still matters.</h3><p>Use the works, passages and rubric assigned by your teacher. Short practice texts prepare skills; longer reading and live performance need their own work.</p><a class="text-link" href="#review">Review learned phrases ${icon('arrow')}</a></section></aside></div>`;
}

function reviewPage(){const learnedCount=learned().length,dueCount=due().length;return intro('Make it stick','A little recall goes a long way.','Review what you’ve learned, with more time for the tricky bits.')+`<div class="grid"><section class="card"><span class="community-mark">↻</span><h2>${dueCount} ${dueCount===1?'phrase is':'phrases are'} ready</h2><p>Review dates adapt to your answers. A phrase you miss returns sooner; a familiar one gets more space.</p><button class="btn" data-action="review" ${dueCount?'':'disabled'}>Review due phrases ${icon('arrow')}</button></section><section class="card"><span class="community-mark">✦</span><h2>${learnedCount} words & phrases learned</h2><p>${learnedCount?'Want a little extra practice? Revisit up to eight familiar phrases at a time.':'Finish a lesson to start your personal review collection.'}</p><button class="btn secondary" data-action="practice" ${learnedCount?'':'disabled'}>Practise learned phrases</button></section></div><p class="footer-note">An incorrect answer is scheduled again in 10 minutes. Correct answers return after 1, 3, 7, 14, 30 and 60 days.<br>Your progress is stored in this browser. Use Settings to export a backup.</p>`;}
function wordsPage(){return intro('Words you can use','Your pocket phrasebook.','Find a phrase, check its meaning, then try it out.')+`<label class="sr-only" for="word-search">Search words and translations</label><input id="word-search" class="search" type="search" placeholder="Search ${esc(course.language)} or ${esc(course.fromLanguage)}…"><div class="note" data-speech-help>${esc(speechHelp())}</div><div id="word-list">${wordRows(allEntries())}</div>`;}
function wordRows(entries){return entries.length?entries.map(e=>`<article class="word-row"><div><h3 dir="auto">${glossedText(e)}</h3><p class="muted">${esc(e.translation)}</p><small>${esc(e.level||'')} · ${esc(e.lessonTitle)} ${progress.cards[cardKey(course,e)]?'· learned':''}</small></div>${audioButton(e)}</article>`).join(''):'<p class="empty">No phrases match your search.</p>';}
function communityPage(){return intro('Language. Together.','Build something worth sharing.','Add a word. Improve a phrase. Open the door to another language.')+`<p><a class="btn secondary" href="#play">Play together in Retro Museum ${icon('arrow')}</a></p><div class="grid"><section class="card"><span class="community-mark">＋</span><h2>You know a phrase. Someone needs it.</h2><p>Use the editor to create a lesson, improve the current course, or start a new language. Try your draft locally, then propose it for community review.</p><div class="actions"><button class="btn" data-action="new-draft">Create a course ${icon('plus')}</button><button class="btn secondary" data-action="fork-draft">Improve this course</button></div>${read(DRAFT,null)?'<p><button class="btn ghost small" data-action="resume-draft">Resume saved draft</button></p>':''}</section><section class="card"><span class="community-mark">↗</span><h2>Open from the first word.</h2><p>The app is <a href="LICENSE.txt" target="_blank" rel="noopener">AGPL v3 or later</a> licensed. Course content is CC BY-SA 4.0: anyone can reuse and improve it with attribution and the same content license.</p><a class="btn secondary" href="${REPO}" target="_blank" rel="noopener">Explore the source ${icon('code')}</a></section></div><section class="card" style="margin-top:20px"><h2>How a contribution becomes a lesson</h2><div class="grid"><div><p class="step">01 · Create & try</p><p>Add words, phrases, translations, notes and accepted answers. Test your course on your device before sharing it.</p><p class="step">02 · Propose</p><p>The editor prepares a GitHub contribution proposal. A GitHub account is needed to submit; no coding is required.</p></div><div><p class="step">03 · Review & publish</p><p>Automated checks validate the file. A fluent speaker checks meaning, natural usage and examples. Maintainers merge approved lessons into the shared course.</p><p class="step">04 · Another language</p><p>The same open course format supports new language pairs. Add a course file and register it, without changing the learning engine.</p></div></div></section><section class="card" style="margin-top:20px"><div class="section-head"><h2>Courses on this device</h2><button class="btn ghost small" data-action="import-course">Import course ${icon('plus')}</button></div>${[...courses,...custom].map(c=>`<div class="course-item"><div><h3>${esc(c.title)}</h3><p>${esc(c.fromLanguage)} → ${esc(c.language)} · ${c.lessons.length} lessons · ${custom.includes(c)?'local draft':c.status==='reviewed'?'reviewed':'awaiting fluent-speaker review'}</p><p>By ${esc(c.author)}${c.attributions?.length?` · based on ${esc([...new Set(c.attributions.map(a=>a.author))].join(', '))}`:c.derivedFrom?` · based on ${esc(c.derivedFrom.author)}`:''} · CC BY-SA 4.0</p></div>${custom.includes(c)?`<button class="btn ghost small" data-action="remove-course" data-id="${esc(c.id)}">Remove</button>`:'<span class="pill">Starter course</span>'}</div>`).join('')}</section><p class="footer-note">Imported drafts stay on your device. Shared course changes go through review on GitHub.<br>Native-speaker recordings can be contributed under the same content license. ${course.id==='fil-en'?'<a href="pronunciation-review/">Listen to and review the pronunciation pilot</a>.':''} Drafts do not automatically become reviewed courses.</p>`;}
function installCard(){return `<section class="card install-card"><span class="pill green">${icon('globe')} Tara, wherever you go</span><h2>${installed?'Tara is on your home screen':'Make room for a little practice.'}</h2><p>Open Tara from your home screen, in its own window. Download lessons below before travelling.</p>${installed?'<p class="saved">Installed on this device</p>':`${installPrompt?'<button class="btn" data-action="install-app">Install Tara</button>':''}<details class="install-help" ${installPrompt?'':'open'}><summary>How to install on your phone</summary><p><strong>iPhone / iPad:</strong> open Tara in Safari, tap Share, then Add to Home Screen and Add.</p><p><strong>Android:</strong> open Tara in Chrome, open the ⋮ menu, then Install app or Add to Home screen.</p></details>`}<p class="field-help">No app store or account needed. Download lessons in the installed app: its storage may be separate from your browser.</p></section>`;}
async function installApp(){const prompt=installPrompt;if(!prompt)return;installPrompt=null;try{await prompt.prompt();await prompt.userChoice;}catch{toast('Use your browser menu to install Tara.');}if(!session&&['settings','downloads'].includes(route))render();}
function formatBytes(value){return value<1e6?`${Math.round(value/1000)} KB`:`${(value/1e6).toFixed(1)} MB`;}
function downloadsPage(){return intro('A little freedom','Your lessons, ready to go.','Choose what to take with you. Available recordings are included in every download.')+`<div class="grid download-intro">${installCard()}<section class="card"><h2>On this device</h2><p id="download-summary">Checking your downloads…</p><p id="download-storage" class="field-help"></p><div class="actions">${navigator.storage?.persist?'<button class="btn secondary small" data-action="protect-downloads">Keep downloads on this device</button>':''}<a class="text-link" href="#settings">Progress & backups ${icon('arrow')}</a></div><p class="field-help">Removing a download keeps your learning progress. Clearing browser data removes both. Backups include progress, not audio.</p></section></div><section class="card download-library"><div class="section-head"><h2>${esc(course.language)} to go</h2><span class="pill green" id="download-connection">${navigator.onLine?'Connected':'You’re offline'}</span></div><div class="download-filters"><label>Find a lesson<input id="download-search" type="search" placeholder="Search lessons…" value="${esc(downloadSearch)}"></label><label>Practice level<select id="download-level" class="field"><option value="all">All levels</option>${courseLevels(course).map(l=>`<option value="${l.id}" ${downloadLevel===l.id?'selected':''}>${l.id} · ${esc(l.title)}</option>`).join('')}</select></label></div><div id="download-job" role="status" aria-live="polite"></div><div class="actions download-bulk"><button class="btn secondary small" data-action="download-shown">${icon('download')} Download shown lessons</button><span class="tiny">Keep Tara open while downloading.</span></div><div id="download-list" class="download-list">Checking available lessons…</div></section>`;}
function filteredDownloadLessons(){return course.lessons.filter(l=>(downloadLevel==='all'||l.level===downloadLevel)&&normalize(`${l.title} ${l.goal}`).includes(normalize(downloadSearch)));}
function renderDownloadList(){
 if(route!=='downloads'||!$('#download-list'))return;
 const available=offlineLibrary.supported&&workerReady&&!workerFailed,items=filteredDownloadLessons();
 $('#download-connection').textContent=navigator.onLine?'Connected':'You’re offline';
 $('#download-list').innerHTML=!offlineLibrary.supported?'<p class="note">Offline downloads need a supported browser over HTTPS. You can keep studying online.</p>':items.map(l=>{const state=downloads.get(l.id)||{state:'checking'},ready=state.state==='ready',busy=!!downloadJob,current=downloadJob?.courseId===course.id&&downloadJob?.lessonId===l.id;return `<article class="download-row" data-lesson="${esc(l.id)}"><span class="download-mark ${ready?'is-ready':''}">${icon(ready?'check':'download')}</span><div class="download-copy"><h3>${esc(l.title)}</h3><p>${esc(l.goal)}</p><span class="download-state ${ready?'saved':''}">${current?'Downloading…':ready?`Ready offline · ${formatBytes(state.bytes)} · ${state.assets.length} recordings${state.missing?' · some audio not available yet':''}`:state.state==='outdated'?'Updated lesson available — download again':state.state==='incomplete'?'Download interrupted — resume when connected':state.state==='checking'?'Checking…':l.level?`${esc(l.level)} · text & available audio`:'Text & available audio'}</span></div><div class="download-buttons">${ready?`<button class="btn secondary small" data-action="start" data-id="${esc(l.id)}">Study</button>`:`<button class="btn ${current?'secondary':'ghost'} small" data-action="download-lesson" data-id="${esc(l.id)}" ${busy||!available||!navigator.onLine?'disabled':''}>${state.state==='outdated'?'Update':state.state==='incomplete'?'Resume':'Download'}</button>`}${['ready','outdated','incomplete'].includes(state.state)?`<button class="icon-btn" data-action="remove-download" data-id="${esc(l.id)}" aria-label="Remove download: ${esc(l.title)}" ${busy?'disabled':''}>${icon('close')}</button>`:''}</div></article>`;}).join('')||'<p class="empty">No lessons match this search.</p>';
 const bulk=$('[data-action="download-shown"]');bulk.disabled=!available||!!downloadJob||!navigator.onLine||!items.some(l=>downloads.get(l.id)?.state!=='ready');
 const j=downloadJob;
 $('#download-job').innerHTML=j?`<div class="download-progress"><div class="section-head"><strong>${esc(j.title)}</strong><button class="btn ghost small" data-action="cancel-download">Cancel download</button></div><progress max="${j.total||1}" value="${j.done}"></progress><p>${j.index} / ${j.count} lessons · ${j.done} / ${j.total} recordings in this lesson · ${formatBytes(j.bytes)}</p></div>`:workerFailed?'<p class="note">Offline setup failed. Reconnect and reload Tara to try again.</p>':!workerReady?'<p class="note">Preparing Tara for offline use…</p>':'';
}
async function refreshDownloads(){
 const selected=course;downloads=new Map();renderDownloadList();
 try{const states=await Promise.all(selected.lessons.map(async l=>[l.id,await offlineLibrary.inspect(selected,l)]));if(course!==selected||route!=='downloads')return;downloads=new Map(states);renderDownloadList();await refreshDownloadStorage();}catch{if(route==='downloads')toast('Could not read downloads. Your browser may have disabled local storage.');}
}
async function refreshDownloadStorage(){
 const summary=await offlineLibrary.summary();if(route!=='downloads'||!$('#download-summary'))return;
 $('#download-summary').textContent=`${summary.count} ${summary.count===1?'lesson':'lessons'} downloaded · ${formatBytes(summary.bytes)} of recordings across your courses.`;
 let protectedStorage=false;try{protectedStorage=await navigator.storage?.persisted?.();}catch{}
 if(route!=='downloads')return;
 $('#download-storage').textContent=protectedStorage?'Downloads are protected from automatic storage cleanup. You can still remove them yourself.':'Your browser manages local storage and may free it when space is low.';
 const button=$('[data-action="protect-downloads"]');if(button){button.disabled=protectedStorage;button.textContent=protectedStorage?'Downloads protected':'Keep downloads on this device';}
}
async function protectDownloads(){try{const granted=await navigator.storage?.persist?.();toast(granted?'Downloads protected from automatic cleanup.':'Your browser is managing storage. Installing Tara can help keep it available.');await refreshDownloadStorage();}catch{toast('Your browser is managing local storage.');}}
async function downloadLessons(lessons){
 if(downloadJob||!lessons.length||!workerReady)return;
 const selected=course,controller=new AbortController();downloadJob={controller,courseId:selected.id,lessonId:'',title:'Preparing your lessons',done:0,total:0,bytes:0,index:0,count:lessons.length};
 try{
  for(const [index,lesson] of lessons.entries()){
   if(controller.signal.aborted)throw new DOMException('Cancelled','AbortError');
   Object.assign(downloadJob,{lessonId:lesson.id,title:lesson.title,index:index+1,done:0,total:0,bytes:0});renderDownloadList();
   await offlineLibrary.download(selected,lesson,{signal:controller.signal,onProgress:value=>{Object.assign(downloadJob,value);renderDownloadList();}});
   if(course===selected)downloads.set(lesson.id,await offlineLibrary.inspect(selected,lesson));
  }
  toast(`${lessons.length===1?'Lesson':'Lessons'} ready offline, with available audio.`);
 }catch(error){toast(error.name==='AbortError'?'Download paused. Tap Resume to finish later.':error.name==='QuotaExceededError'?'Not enough space. Remove some downloads and try again.':error.message||'Download failed. Reconnect and tap Resume.');}
 finally{downloadJob=null;if(route==='downloads')await refreshDownloads();}
}
async function removeDownload(id){
 if(downloadJob)return;const selected=course,lesson=course.lessons.find(l=>l.id===id);if(!lesson)return;
 try{await offlineLibrary.remove(selected,lesson);if(course===selected)await refreshDownloads();toast('Download removed. Your learning progress is kept.');}catch{toast('This download could not be removed. Try again.');}
}

function settingsPage(){return intro('Your learning, your way','Keep your progress close.','No account for lessons. No ads. No paid features.')+`<div class="grid"><section class="card"><h2>Progress & backups</h2><p>${esc(course.learnerName||'Your')}${course.learnerName?'’s':''} completed lessons, XP and review dates are saved automatically in this browser’s local storage. They are restored when you reopen the app on this device.</p><div class="actions"><button class="btn secondary" data-action="save-progress">Save progress on this device</button><button class="btn" data-action="export-progress">Export backup ${icon('download')}</button><button class="btn secondary" data-action="import-progress">Restore backup</button></div><p class="field-help">Export before changing devices or clearing browser data. Backups also include imported local courses. Editor drafts must be exported separately.</p></section>${installCard()}<section class="card"><h2>Lessons to go</h2><p>Choose lessons to download, including phrases, readings, model responses and their available audio. Study without a connection.</p><a class="btn secondary" href="#downloads">Manage downloads ${icon('download')}</a></section><section class="card"><h2>Sound & pronunciation</h2><p data-speech-help>${esc(speechHelp())}</p><div class="actions">${audioButton(allEntries()[0])}${audioButton(allEntries()[0],true)}</div><p class="field-help">Sound uses stored recordings; browser text-to-speech is disabled. Synthetic recordings are identified in their review metadata. The first lesson’s audio is downloaded with the app. Download any lesson with its audio in Downloads. Other recordings are also cached after listening. Slower playback changes speed while preserving pitch.</p></section><section class="card"><h2>A fresh start</h2><p>Reset completed lessons, XP and review dates. Export a backup first if you want to keep them.</p><button class="btn ghost" data-action="reset">Reset learning progress</button></section></div><section class="note" style="margin-top:20px">Tara! v0.1 · A community-built starting point. Course examples are drafts pending fluent-speaker review. This app contains no advertising, analytics scripts or external AI services. The learning app sends no text to a speech or AI provider. Audio generation is an offline maintainer task. <a href="${REPO}/blob/main/PRIVACY.md" target="_blank" rel="noopener">Privacy details</a>.</section>`;}
function render(){
 wordGlosses.close();
 if(!course)return;
 route=location.hash.slice(1)||'learn';
 if(session){renderSession();return;}
 if(result){renderResult();return;}
 const pages={learn:home,school:schoolPage,play:playPage,review:reviewPage,words:wordsPage,community:communityPage,settings:settingsPage,downloads:downloadsPage,editor:editorPage};
 if(!pages[route])route='learn';
 $('#app').innerHTML=shell(pages[route]());
 $('#course-select').addEventListener('change',e=>{save();speech.stop();course=[...courses,...custom].find(c=>c.id===e.target.value);loadProgress();persist('tara-selected',course.id);render();});
 if(route==='downloads'){refreshDownloads();$('#download-search').addEventListener('input',e=>{downloadSearch=e.target.value;renderDownloadList();});$('#download-level').addEventListener('change',e=>{downloadLevel=e.target.value;renderDownloadList();});}
 if(route==='play')$('#quiz-selection').addEventListener('change',e=>{persist(`tara-quiz-${course.id}`,e.target.value);render();});
 if(route==='words')$('#word-search').addEventListener('input',e=>{$('#word-list').innerHTML=wordRows(allEntries().filter(x=>normalize(`${x.text} ${x.translation}`).includes(normalize(e.target.value))));});
 if(route==='editor')$('#editor-lesson-picker').addEventListener('change',e=>{captureDraft();persist(DRAFT,draft);draftLessonIndex=Number(e.target.value);render();});
 if(route==='editor')$('#course-editor').addEventListener('input',()=>{captureDraft();persist(DRAFT,draft);$('#draft-status').textContent='Draft saved on this device';});
}
function startLesson(id){
 const lesson=course.lessons.find(l=>l.id===id);if(!lesson)return;
 speech.stop();result=null;
 session={returnRoute:route==='school'?'school':'learn',lesson,entries:lesson.entries,phase:'learn',index:0,queue:lessonQueue(lesson,shuffle),answers:[],selected:null,checked:false,tokens:[],chosen:[],writing:progress.writing?.[`${course.id}:${lesson.id}`]?.text||'',showModel:false};
 renderSession();window.scrollTo(0,0);
}
function startReview(all=false){const entries=shuffle(all?learned():due()).slice(0,8);if(!entries.length)return;speech.stop();result=null;session={lesson:{id:'review',title:'A little recall'},entries,phase:'exercise',index:0,queue:entries.map(entry=>({entry,type:entry.text.trim().split(/\s+/).length>1?'build':'type',retried:false})),answers:[],selected:null,checked:false,tokens:[],chosen:[]};prepareQuestion();renderSession();window.scrollTo(0,0);}
function prepareQuestion(){
 const q=session.queue[session.index];session.selected=null;session.checked=false;session.input='';session.chosen=[];
 if(q.type==='comprehension'){session.options=shuffle(q.question.options.map((translation,i)=>({id:String(i),translation})));return;}
 session.tokens=shuffle(q.entry.text.trim().split(/\s+/).map((text,i)=>({text,id:i})));
 const seen=new Set([normalize(q.entry.translation)]),level=session.lesson.level;
 const pool=allEntries().filter(e=>!level||!e.level||levelIndex(e.level)<=levelIndex(level));
 const other=shuffle(pool).filter(e=>{const v=normalize(e.translation);if(seen.has(v))return false;seen.add(v);return true;}).slice(0,3);
 session.options=shuffle([q.entry,...other]);
}
function passage(lesson){const r=lesson.reading;return `<article class="reading-card"><h2>${esc(r.title)}</h2><p class="passage-text" dir="auto">${esc(r.text)}</p>${audioControls({id:`reading:${lesson.id}`,text:r.text,audio:r.audio,audioReview:r.audioReview})}${r.attribution||r.source?`<p class="school-source">${esc(r.attribution||'')}${r.source?` <a href="${esc(r.source)}" target="_blank" rel="noopener">Source text</a>`:''}</p>`:''}<details><summary>Show ${esc(course.fromLanguage)} support</summary><p class="muted">${esc(r.translation)}</p></details></article>`;}
function renderSession(){
 wordGlosses.close();
 const s=session,teaching=s.phase==='learn',isReview=s.lesson.id==='review';
 const learnCount=isReview?0:s.entries.length,readCount=s.lesson.reading?1:0,taskCount=s.lesson.task?1:0;
 const total=learnCount+readCount+s.queue.length+taskCount;
 const done=teaching?s.index:s.phase==='reading'?learnCount:s.phase==='task'?total-1:learnCount+readCount+s.index;
 let body='';
 if(teaching){const entry=s.entries[s.index];body=`<p class="eyebrow">${esc(s.lesson.level||'')} · ${esc(s.lesson.title)} · Make it familiar</p><h1 class="session-title">A phrase for your next conversation.</h1><div class="study-card"><span class="pill green">${esc(entry.kind)} · ${esc(course.language)}</span><h2 class="study-text" dir="auto">${glossedText(entry)}</h2>${validGlosses(entry)?'<p class="gloss-hint">Hover over or tap a word for its meaning here.</p>':''}${audioControls(entry)}<p class="study-translation">${esc(entry.translation)}</p><p class="study-note">${esc(entry.note||'Read it once, then try saying it aloud.')}</p></div>${s.index===0&&s.lesson.tip?`<div class="note">${esc(s.lesson.tip)}</div>`:''}<div class="session-bottom"><p>${s.index+1} of ${s.entries.length} new phrases</p><button class="btn" data-action="learn-next">${s.index===s.entries.length-1?(s.lesson.reading?'Read in context':'Let’s practise'):'Got it'} ${icon('arrow')}</button></div>`;}
 else if(s.phase==='reading'){
 body=`<p class="eyebrow">${esc(s.lesson.level||'')} · Read & understand</p><h1 class="session-title">${esc(s.lesson.goal)}</h1>${passage(s.lesson)}<div class="session-bottom"><p>Try the text first. English support is there if you need it.</p><button class="btn" data-action="reading-next">Let’s practise ${icon('arrow')}</button></div>`;
 }else if(s.phase==='task'){
 const task=s.lesson.task;
 body=`<p class="eyebrow">${esc(s.lesson.level||'')} · Make the language your own</p><h1 class="session-title">Your turn to express an idea.</h1><div class="note">${esc(task.prompt)}</div><label for="writing-response" style="margin-top:24px">Your response in ${esc(course.language)}</label><textarea id="writing-response" maxlength="6000" rows="8" placeholder="There is more than one good answer…">${esc(s.writing)}</textarea><p class="tiny">Your text is saved in localStorage when you choose Save & compare. Free expression is self-assessed; it is not marked wrong for differing from the example.</p>${s.showModel?`<section class="reading-card"><h2>One possible response</h2><p class="passage-text" dir="auto">${esc(task.model)}</p>${audioControls({...task,id:`task:${s.lesson.id}`,text:task.model})}<h3>Check your own work</h3>${task.checklist.map((item,i)=>`<label class="checkbox-label"><input type="checkbox"><span>${esc(item)}</span></label>`).join('')}<p class="tiny">For feedback on natural usage and school expectations, ask a fluent speaker or teacher to read your work.</p></section>`:''}<div class="actions" style="margin:16px 0 24px"><button class="btn secondary" id="save-writing" data-action="writing-save" ${s.writing.trim()?'':'disabled'}>Save & compare</button>${s.showModel?'':'<button class="btn ghost" data-action="writing-skip">Practise writing later</button>'}</div>${s.showModel?'<div class="session-bottom"><p>Practice progress is separate from a proficiency assessment.</p><button class="btn" data-action="writing-finish">Finish lesson</button></div>':''}`;
 }else{
 const q=s.queue[s.index],comp=q.type==='comprehension',entry=q.entry;
 const correctId=comp?String(q.question.answer):entry.id;
 body=`<p class="eyebrow">${esc(s.lesson.title)} ${q.retried?'· One more try':''}</p><h1 class="session-title">${comp?'Read for meaning.':q.type==='choice'?'What does this mean?':q.type==='build'?'Build the phrase.':'Write it in '+esc(course.language)+'.'}</h1>${comp?`<details class="reading-recall"><summary>Read the passage again</summary>${passage(s.lesson)}</details>`:''}<div class="question-prompt" dir="auto">${esc(comp?q.question.prompt:q.type==='choice'?entry.text:entry.translation)}</div>${q.type==='choice'?audioControls(entry):''}`;
 if(comp||q.type==='choice')body+=`<div class="choices">${s.options.map((o,i)=>`<button class="choice ${s.selected===o.id?'selected':''} ${s.checked&&o.id===correctId?'correct':''} ${s.checked&&s.selected===o.id&&o.id!==correctId?'wrong':''}" data-action="choice" data-id="${esc(o.id)}" ${s.checked?'disabled':''}><span class="key">${i+1}</span>${esc(o.translation)}</button>`).join('')}</div>`;
 if(q.type==='build')body+=`<p class="tiny">Tap the words in order. Tap a chosen word to put it back.</p><div class="token-answer" aria-label="Your answer">${s.chosen.map(id=>{const t=s.tokens.find(x=>x.id===id);return `<button class="token" data-action="untoken" data-index="${id}" ${s.checked?'disabled':''}>${esc(t.text)}</button>`;}).join('')}${!s.chosen.length?'<span class="tiny">Your phrase goes here…</span>':''}</div><div class="token-bank">${s.tokens.map(t=>`<button class="token" data-action="token" data-index="${t.id}" ${s.chosen.includes(t.id)||s.checked?'disabled':''}>${esc(t.text)}</button>`).join('')}</div>`;
 if(q.type==='type')body+=`<label class="sr-only" for="answer-input">Your answer in ${esc(course.language)}</label><input class="answer-input" id="answer-input" autocomplete="off" autocapitalize="none" spellcheck="false" placeholder="Type your answer…" value="${esc(s.input)}" ${s.checked?'disabled':''}>`;
 if(s.checked)body+=`<div class="feedback ${s.correct?'':'bad'}" role="status"><h3>${s.correct?'Nice work!':'You’re learning. Try it this way:'}</h3><p>${comp?`${s.correct?'':`<strong>${esc(q.question.options[q.question.answer])}</strong><br>`}${esc(q.question.explanation)}`:`${s.correct?'':`<strong>${esc(entry.text)}</strong> · ${esc(entry.translation)}<br>`}${esc(entry.note||'You’ll see this phrase again in your reviews.')}`}</p>${comp?'':audioControls(entry)}</div>`;
 const ready=comp||q.type==='choice'?s.selected!==null:q.type==='build'?s.chosen.length>0:!!s.input?.trim();
 body+=`<div class="session-bottom"><p>${s.checked?(s.correct?'A little more confident.':'Mistakes help us learn.'):'Take your time. No hearts to lose.'}</p><button class="btn" id="check-answer" data-action="${s.checked?'exercise-next':'check'}" ${!s.checked&&!ready?'disabled':''}>${s.checked?'Continue':'Check answer'} ${icon('arrow')}</button></div>`;
 }
 $('#app').innerHTML=`<main class="session-shell"><div class="session-top"><button class="icon-btn" data-action="leave" aria-label="Leave lesson">${icon('close')}</button><div class="progress-track" role="progressbar" aria-label="Lesson progress" aria-valuemin="0" aria-valuemax="${total}" aria-valuenow="${done}"><div class="progress-fill" style="width:${Math.round(done/total*100)}%"></div></div><span class="session-counter">${teaching?'Learn':s.phase==='reading'?'Read':s.phase==='task'?'Express':'Practise'}</span></div>${body}</main>`;
 if($('#answer-input'))$('#answer-input').addEventListener('input',e=>{session.input=e.target.value;$('#check-answer').disabled=!session.input.trim();});
 if($('#writing-response'))$('#writing-response').addEventListener('input',e=>{session.writing=e.target.value;$('#save-writing').disabled=!session.writing.trim();});
}
function checkAnswer(){
 const s=session;if(!s||s.checked)return;const q=s.queue[s.index];
 if(q.type==='comprehension')s.correct=s.selected===String(q.question.answer);
 else{const text=q.type==='choice'?s.selected:q.type==='build'?s.chosen.map(id=>s.tokens.find(t=>t.id===id).text).join(' '):s.input;s.correct=q.type==='choice'?s.selected===q.entry.id:accepts(text,q.entry,course.languageCode);}
 s.checked=true;s.answers.push({...(q.entry?{entry:q.entry}:{}),correct:s.correct});
 if(!s.correct&&!q.retried)s.queue.push({...q,retried:true});
 renderSession();$('#check-answer')?.focus();
}
function finish(){const s=session;const outcome=finishSession(progress,course,s.lesson.id,s.answers);progress=outcome.progress;const saved=save();result={...outcome,saved,returnRoute:s.returnRoute,title:s.lesson.title,review:s.lesson.id==='review',entries:s.entries};session=null;renderResult();window.scrollTo(0,0);}
function renderResult(){const r=result;$('#app').innerHTML=`<main class="session-shell"><div class="result"><div class="result-symbol">✦</div><p class="eyebrow">You showed up. That matters.</p><h1>${r.review?'A little stronger.':'One conversation closer.'}</h1><p class="muted">${esc(r.title)} · Session complete</p><div class="result-stats"><div><strong>+${r.xp}</strong><span>XP earned</span></div><div><strong>${r.accuracy}%</strong><span>Correct attempts</span></div><div><strong>${streak(progress.activity)}</strong><span>Day streak</span></div></div><div class="note">Try this in real life today:<br><strong>${esc(r.entries[0].text)}</strong> — ${esc(r.entries[0].translation)}</div><p class="footer-note">${!r.saved?'This browser could not save your progress. Return to Settings and export a backup.':r.xp===0?'You already earned XP for this session today. Your reviews are still updated.':'Your progress and review dates are saved on this device.'}</p><button class="btn" data-action="back-path">Back to your path ${icon('arrow')}</button></div></main>`;}
function download(name,value){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)+'\n'],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function pickFile(callback){const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.addEventListener('change',async()=>{try{const file=input.files[0];if(!file)return;if(file.size>2000000)throw new Error('Choose a JSON file smaller than 2 MB.');await callback(JSON.parse(await file.text()));}catch(e){toast(e.message||'Could not read this file.');}});input.click();}
function addCourse(value){const errors=validateCourse(value);if(errors.length)throw new Error(errors.slice(0,3).join(' '));const copy=structuredClone(value);copy.status='draft';copy.reviewers=[];if(courses.some(c=>c.id===copy.id))copy.id=`local-${copy.id}`.slice(0,64);const index=custom.findIndex(c=>c.id===copy.id);if(index>=0)custom[index]=copy;else custom.push(copy);if(!persist(CUSTOM,custom))return;save();course=copy;loadProgress();persist('tara-selected',course.id);nextRoute('learn');toast('Local draft ready to try. It has not been published.');}
function newDraft(fork=false){draftLessonIndex=0;if(fork){draft=forkCourse(course);}else draft={schemaVersion:1,id:'my-course',title:'',language:'',languageCode:'',fromLanguage:'English',fromCode:'en',author:'',license:'CC-BY-SA-4.0',status:'draft',reviewers:[],lessons:[blankLesson()]};persist(DRAFT,draft);nextRoute('editor');}
function uid(prefix){return `${prefix}-${crypto.randomUUID().slice(0,8)}`;}
function blankEntry(){return {id:uid('phrase'),kind:'phrase',text:'',translation:'',note:''};}
function blankLesson(){return {id:uid('lesson'),title:'',goal:'',tip:'',entries:[blankEntry()]};}
function field(label,name,value,extra=''){return `<div class="field-group"><label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" value="${esc(value)}" ${extra}></div>`;}
function textArea(label,name,value,max=7000){return `<div class="field-group"><label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}" maxlength="${max}" rows="5">${esc(value||'')}</textarea></div>`;}
function schoolFields(l,i){return `<details class="lesson-extension"><summary>School pathway & source (optional)</summary><p class="tiny">Mappings stay drafts until an educator checks the actual competency and source.</p><label for="school-stage-${i}">School stage</label><select class="field" id="school-stage-${i}" name="l${i}-school-stage"><option value="">No school mapping</option><option value="foundations" ${l.foundation?'selected':''}>Foundations / Grade 1 prerequisites</option>${[2,3,4,5,6,7,8].map(g=>`<option value="${g}" ${l.school?.grade===g?'selected':''}>Grade ${g}</option>`).join('')}</select><label for="school-quarter-${i}">Quarter</label><select class="field" id="school-quarter-${i}" name="l${i}-school-quarter">${[1,2,3,4].map(q=>`<option value="${q}" ${l.school?.quarter===q?'selected':''}>Quarter ${q}</option>`).join('')}</select>${field('Curriculum source (HTTPS)',`l${i}-school-source`,l.school?.source||SCHOOL_SOURCE,'maxlength="1000"')}${textArea('Skills practiced (one per line)',`l${i}-school-skills`,(l.school?.skills||[]).join('\n'),2400)}</details>`;}
function lessonExtensionFields(l,i){return `${schoolFields(l,i)}<div class="field-group"><label for="level-${i}">Practice target (optional)</label><select class="field" id="level-${i}" name="l${i}-level"><option value="">No CEFR target</option>${CEFR_LEVELS.map(v=>`<option value="${v.id}" ${l.level===v.id?'selected':''}>${v.id} · ${v.title}</option>`).join('')}</select></div>${l.reading?`<details class="lesson-extension"><summary>Reading & comprehension · ${l.reading.questions.length} questions</summary>${field('Reading title',`l${i}-reading-title`,l.reading.title,'maxlength="150"')}${field('Reading source (HTTPS, optional)',`l${i}-reading-source`,l.reading.source||'','maxlength="1000"')}${textArea('Attribution / historical excerpt credit (optional)',`l${i}-reading-attribution`,l.reading.attribution||'',1200)}${textArea('Reading in the learning language',`l${i}-reading-text`,l.reading.text)}${textArea('Instruction-language support translation',`l${i}-reading-translation`,l.reading.translation)}${l.reading.questions.map((q,j)=>`<div class="question-editor">${field(`Question ${j+1}`,`l${i}q${j}-prompt`,q.prompt,'maxlength="500"')}${q.options.map((v,k)=>field(`Option ${k+1}`,`l${i}q${j}-option${k}`,v,'maxlength="500"')).join('')}<label for="answer-${i}-${j}">Correct option</label><select class="field" id="answer-${i}-${j}" name="l${i}q${j}-answer">${q.options.map((_,k)=>`<option value="${k}" ${q.answer===k?'selected':''}>Option ${k+1}</option>`).join('')}</select>${textArea('Why this answer fits the text',`l${i}q${j}-explanation`,q.explanation,1200)}<button type="button" class="btn ghost small" data-action="remove-question" data-lesson="${i}" data-index="${j}" ${l.reading.questions.length===1?'disabled':''}>Remove question</button></div>`).join('')}<div class="actions"><button type="button" class="btn secondary small" data-action="add-question" data-index="${i}">Add comprehension question</button><button type="button" class="btn ghost small" data-action="remove-reading" data-index="${i}">Remove reading</button></div></details>`:`<button type="button" class="btn secondary small" data-action="add-reading" data-index="${i}">Add reading & comprehension</button>`}${l.task?`<details class="lesson-extension"><summary>Expression task & self-check</summary>${textArea('Expression task instructions',`l${i}-task-prompt`,l.task.prompt,1600)}${textArea('One possible response in the learning language',`l${i}-task-model`,l.task.model)}${textArea('Self-check points (one per line)',`l${i}-task-checklist`,l.task.checklist.join('\n'),3200)}<button type="button" class="btn ghost small" data-action="remove-task" data-index="${i}">Remove expression task</button></details>`:`<button type="button" class="btn secondary small" data-action="add-task" data-index="${i}">Add expression task</button>`}`;}
function glossFields(e,i,j){return `<details class="lesson-extension gloss-editor" data-gloss-editor data-text="${esc(e.text)}"><summary>Word meanings in this sentence</summary><p class="field-help">Short English meanings for this exact use, including grammatical particles. Leave a meaning blank to omit word hints for this phrase. After changing the phrase, choose Refresh words.</p><div class="form-grid">${wordTokens(e.text).map((w,k)=>field(w.text,`l${i}e${j}-gloss${k}`,validGlosses(e)?e.glosses[k].meaning:'','maxlength="240"')).join('')}</div><button type="button" class="btn secondary small" data-action="refresh-glosses">Refresh words</button></details>`;}
function editorPage(){if(draft&&draftLessonIndex>=draft.lessons.length)draftLessonIndex=0;if(!draft){const saved=read(DRAFT,null);draft=saved||{schemaVersion:1,id:'my-course',title:'',language:'',languageCode:'',fromLanguage:'English',fromCode:'en',author:'',license:'CC-BY-SA-4.0',status:'draft',reviewers:[],lessons:[blankLesson()]};}return intro('Made by the community','Give someone their next words.','Create a course, try it locally, then propose it for review.')+`<div class="note">Your draft is saved on this device as you type. Publishing a shared course requires community review. Existing course content keeps its original attribution.</div><form id="course-editor"><section class="card" style="margin-top:20px"><h2>The course</h2><div class="form-grid">${field('Course title','title',draft.title,'maxlength="100" required')}${field('Course id','id',draft.id,'maxlength="64" pattern="[a-z][a-z0-9-]*" required')}${field('Learning language','language',draft.language,'placeholder="e.g. Filipino" maxlength="100" required')}${field('Language code','languageCode',draft.languageCode,'placeholder="e.g. fil, ja, es" maxlength="20" required')}${field('Instruction language','fromLanguage',draft.fromLanguage,'maxlength="100" required')}${field('Instruction language code','fromCode',draft.fromCode,'maxlength="20" required')}${field('Your attribution / contributor name','author',draft.author,'placeholder="A name or public pseudonym" maxlength="100" required')}</div><p class="field-help">The learning engine supports other languages and scripts. Interface navigation is currently in English. Words, translations and lesson explanations come from the course.</p></section><div class="field-group" style="margin-top:20px"><label for="editor-lesson-picker">Lesson to edit</label><select id="editor-lesson-picker" class="field">${draft.lessons.map((l,i)=>`<option value="${i}" ${i===draftLessonIndex?'selected':''}>${i+1}. ${esc(l.title||'Untitled lesson')} ${l.level?`· ${l.level}`:''}</option>`).join('')}</select><p class="field-help">One lesson is shown at a time. Export includes the entire course.</p></div>${draft.lessons.map((lesson,index)=>({lesson,index})).filter(x=>x.index===draftLessonIndex).map(({lesson:l,index:i})=>`<section class="editor-lesson"><div class="section-head"><h2>Lesson ${i+1}</h2><button type="button" class="btn ghost small" data-action="remove-lesson" data-index="${i}" ${draft.lessons.length===1?'disabled':''}>Remove lesson</button></div><div class="form-grid">${field('Lesson title',`l${i}-title`,l.title,'maxlength="100" required')}${field('Practical goal',`l${i}-goal`,l.goal,'placeholder="What can the learner do afterwards?" maxlength="300" required')}</div>${field('A short teaching tip',`l${i}-tip`,l.tip||'','maxlength="1000"')}${lessonExtensionFields(l,i)}${l.entries.map((e,j)=>`<div class="editor-entry"><div class="entry-heading"><span>Word or phrase ${j+1}</span><button type="button" class="btn ghost small" data-action="remove-entry" data-lesson="${i}" data-index="${j}" ${l.entries.length===1?'disabled':''}>Remove</button></div><div class="form-grid">${field('Learning-language text',`l${i}e${j}-text`,e.text,'maxlength="300" required')}${field('Meaning / translation',`l${i}e${j}-translation`,e.translation,'maxlength="300" required')}</div><div class="form-grid"><div class="field-group"><label for="kind-${i}-${j}">Entry type</label><select class="field" id="kind-${i}-${j}" name="l${i}e${j}-kind"><option value="phrase" ${e.kind==='phrase'?'selected':''}>Phrase</option><option value="word" ${e.kind==='word'?'selected':''}>Word</option></select></div>${field('Usage note',`l${i}e${j}-note`,e.note||'','maxlength="600"')}</div>${field('Other accepted spellings (separate with |)',`l${i}e${j}-accepted`,(e.accepted||[]).join(' | '),'maxlength="1000"')}${glossFields(e,i,j)}</div>`).join('')}<button type="button" class="btn secondary small" data-action="add-entry" data-index="${i}">${icon('plus')} Add a word or phrase</button></section>`).join('')}<button type="button" class="btn secondary" data-action="add-lesson">${icon('plus')} Add a lesson</button><label class="checkbox-label"><input type="checkbox" id="content-license" ${draft.agreed?'checked':''}> <span>I wrote these additions or have permission to share them. I agree to publish my course contributions under <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a>, with attribution. I have not copied a proprietary course.</span></label><div id="editor-errors" role="alert"></div><div class="editor-footer"><div class="actions"><button type="button" class="btn secondary" data-action="try-draft">Try on my device</button><button type="button" class="btn secondary" data-action="export-draft">Export JSON ${icon('download')}</button><button type="button" class="btn" data-action="propose">Propose contribution ${icon('arrow')}</button></div><p id="draft-status" class="saved" style="margin:10px 0 0">Draft stays on this device until you export or submit it.</p></div></form>`;}
function captureDraft(){const f=$('#course-editor');if(!f)return;const data=new FormData(f);for(const key of ['title','id','language','languageCode','fromLanguage','fromCode','author'])draft[key]=String(data.get(key)||'').trim();draft.agreed=$('#content-license').checked;draft.lessons.forEach((l,i)=>{if(!data.has(`l${i}-title`))return;for(const key of ['title','goal','tip'])l[key]=String(data.get(`l${i}-${key}`)||'').trim();l.entries.forEach((e,j)=>{const rendered=f.elements.namedItem(`l${i}e${j}-text`)?.closest('.editor-entry')?.querySelector('[data-gloss-editor]');const glossaryText=rendered?.dataset.text,previousText=e.text;for(const key of ['text','translation','kind','note'])e[key]=String(data.get(`l${i}e${j}-${key}`)||'').trim();if(e.text!==previousText){delete e.audio;delete e.audioReview;}e.accepted=String(data.get(`l${i}e${j}-accepted`)||'').split('|').map(s=>s.trim()).filter(Boolean);if(!e.accepted.length)delete e.accepted;const words=wordTokens(e.text);const glosses=words.map((w,k)=>({text:w.text,meaning:String(data.get(`l${i}e${j}-gloss${k}`)||'').trim()}));if(glossaryText===e.text&&glosses.length&&glosses.every(g=>g.meaning))e.glosses=glosses;else delete e.glosses;});if(!l.tip)delete l.tip;const level=String(data.get(`l${i}-level`)||'');if(level)l.level=level;else delete l.level;
const schoolStage=String(data.get(`l${i}-school-stage`)||'');if(schoolStage==='foundations'){l.foundation=true;delete l.school;}else if(schoolStage){delete l.foundation;l.school={program:'DepEd-MATATAG',grade:Number(schoolStage),quarter:Number(data.get(`l${i}-school-quarter`)),source:String(data.get(`l${i}-school-source`)||'').trim(),skills:String(data.get(`l${i}-school-skills`)||'').split('\n').map(x=>x.trim()).filter(Boolean)};}else{delete l.foundation;delete l.school;}
if(l.reading){if(l.reading.text!==String(data.get(`l${i}-reading-text`)||'').trim()){delete l.reading.audio;delete l.reading.audioReview;}for(const key of ['source','attribution']){const v=String(data.get(`l${i}-reading-${key}`)||'').trim();if(v)l.reading[key]=v;else delete l.reading[key];}for(const key of ['title','text','translation'])l.reading[key]=String(data.get(`l${i}-reading-${key}`)||'').trim();l.reading.questions.forEach((q,j)=>{q.prompt=String(data.get(`l${i}q${j}-prompt`)||'').trim();q.explanation=String(data.get(`l${i}q${j}-explanation`)||'').trim();q.answer=Number(data.get(`l${i}q${j}-answer`));q.options=q.options.map((_,k)=>String(data.get(`l${i}q${j}-option${k}`)||'').trim());});}
if(l.task){if(l.task.model!==String(data.get(`l${i}-task-model`)||'').trim()){delete l.task.audio;delete l.task.audioReview;}for(const key of ['prompt','model'])l.task[key]=String(data.get(`l${i}-task-${key}`)||'').trim();l.task.checklist=String(data.get(`l${i}-task-checklist`)||'').split('\n').map(v=>v.trim()).filter(Boolean);}});}
function validDraft(requireLicense=false){captureDraft();const value=structuredClone(draft);delete value.agreed;const errors=validateCourse(value);if(requireLicense&&!draft.agreed)errors.push('Please confirm the content license before sharing.');$('#editor-errors').innerHTML=errors.length?`<div class="errors"><strong>Please check these details:</strong><ul>${errors.map(e=>`<li>${esc(e)}</li>`).join('')}</ul></div>`:'';if(errors.length){$('#editor-errors').scrollIntoView({behavior:'smooth',block:'center'});return null;}return value;}
function propose(){const value=validDraft(true);if(!value)return;download(`${value.id}.json`,value);let body=`## Course contribution\n\n- Language pair: ${value.fromLanguage} → ${value.language}\n- Contributor: ${value.author}\n- [x] I have the right to share these additions under CC BY-SA 4.0.\n- [ ] Fluent-speaker review requested\n\n`;const content=JSON.stringify(value,null,2);if(content.length<4500)body+='```json\n'+content+'\n```';else body+='Please attach the exported JSON file here (GitHub accepts a .json file inside a .zip archive, or paste its contents in a fenced code block).';const a=document.createElement('a');a.href=`${REPO}/issues/new?title=${encodeURIComponent('[Course] '+value.title)}&body=${encodeURIComponent(body)}`;a.target='_blank';a.rel='noopener';a.click();toast('JSON exported. Review and submit your proposal on GitHub.');}
function restoreBackup(value,restored){const restoredCourses=value.courses.map(c=>({...c,status:'draft',reviewers:[]}));const learner=value.learnerId||'default';const target=[...courses,...restoredCourses].find(c=>(c.learnerId||'default')===learner);if(!target){toast('Import this learner’s course before restoring their progress.');return;}save();custom=restoredCourses;course=target;progress=restored;save();persist(CUSTOM,custom);persist('tara-selected',course.id);render();toast('Backup restored for '+(value.learnerName||'this learner')+'.');}
const actions={
 start:b=>startLesson(b.dataset.id),review:()=>startReview(),practice:()=>startReview(true),audio:b=>{const e=allEntries().find(e=>e.id===b.dataset.id)||course.lessons.flatMap(l=>[{id:`reading:${l.id}`,...l.reading,text:l.reading?.text},{id:`task:${l.id}`,...l.task,text:l.task?.model}]).find(e=>e.id===b.dataset.id&&e.text);if(e)speak(e,Number(b.dataset.rate)||1);},
 leave:()=>confirmAction('Leave this lesson?','This unfinished session will be lost. Completed lessons are saved.',()=>{speech.stop();session=null;render();}),
 'play-museum':b=>openMuseum(b.dataset.id),
 'export-quiz':b=>download(`tara-${b.dataset.id}.quiz.json`,createMuseumQuiz(course,b.dataset.id)),
 'school-stage':b=>{persist(`tara-school-${course.id}`,b.dataset.id);render();document.querySelector('#school-lessons')?.scrollIntoView({block:'start'});},
 'level':b=>{persist(`tara-level-${course.id}`,b.dataset.id);render();},
 'learn-next':()=>{speech.stop();session.index++;if(session.index>=session.entries.length){session.phase=session.lesson.reading?'reading':'exercise';session.index=0;if(session.phase==='exercise')prepareQuestion();}renderSession();window.scrollTo(0,0);},
 'reading-next':()=>{speech.stop();session.phase='exercise';session.index=0;prepareQuestion();renderSession();window.scrollTo(0,0);},
 choice:b=>{session.selected=b.dataset.id;renderSession();},token:b=>{session.chosen.push(Number(b.dataset.index));renderSession();},untoken:b=>{session.chosen=session.chosen.filter(x=>x!==Number(b.dataset.index));renderSession();},check:checkAnswer,
 'exercise-next':()=>{speech.stop();session.index++;if(session.index>=session.queue.length){if(session.lesson.task){session.phase='task';renderSession();window.scrollTo(0,0);}else finish();}else{prepareQuestion();renderSession();window.scrollTo(0,0);}},
 'writing-save':()=>{if(!session.writing.trim())return;progress.writing[`${course.id}:${session.lesson.id}`]={text:session.writing,updated:Date.now()};if(save())toast('Your response is saved on this device.');session.showModel=true;renderSession();},
 'writing-skip':finish,
 'writing-finish':()=>{if(session.writing.trim()){progress.writing[`${course.id}:${session.lesson.id}`]={text:session.writing,updated:Date.now()};}finish();},
 'back-path':()=>{const destination=result?.returnRoute||'learn';result=null;location.hash=destination;render();window.scrollTo(0,0);},
 'install-app':installApp,
 'download-lesson':b=>downloadLessons(course.lessons.filter(l=>l.id===b.dataset.id)),
 'download-shown':()=>downloadLessons(filteredDownloadLessons().filter(l=>downloads.get(l.id)?.state!=='ready')),
 'cancel-download':()=>downloadJob?.controller.abort(),
 'remove-download':b=>removeDownload(b.dataset.id),
 'protect-downloads':protectDownloads,
 'save-progress':()=>{if(save())toast('Progress saved on this device. It will be restored when you reopen Tara.');},
 'export-progress':()=>download('tara-backup-'+(course.learnerId?course.learnerId+'-':'')+localDay()+'.json',{format:'tara-backup',version:1,learnerId:course.learnerId||'default',learnerName:course.learnerName||'Marco',progress,courses:custom}),
 'import-progress':()=>pickFile(value=>{if(value.format!=='tara-backup'||value.version!==1||!Array.isArray(value.courses)||value.courses.length>100)throw new Error('This is not a Tara backup.');const restored=safeProgress(value.progress);const ids=new Set();for(const c of value.courses){const errors=validateCourse(c);if(errors.length||ids.has(c.id)||courses.some(x=>x.id===c.id))throw new Error('Backup contains an invalid or duplicate course.');ids.add(c.id);}confirmAction('Restore this backup?',`This restores ${value.learnerName||'the saved learner'}’s progress and replaces imported courses on this device.`,()=>{restoreBackup(value,restored);});}),
 reset:()=>confirmAction('Reset your learning progress?','This removes XP, completed lessons and review dates from this device. Imported courses and editor drafts are kept.',()=>{progress=freshProgress();save();render();toast('Learning progress reset.');}),
 'import-course':()=>pickFile(value=>{const errors=validateCourse(value);if(errors.length)throw new Error(errors.slice(0,3).join(' '));confirmAction('Import this course?',`${value.title} (${value.lessons.length} lessons) will be saved as a local, unreviewed draft. An existing local course with the same id will be replaced.`,()=>addCourse(value));}),
 'remove-course':b=>confirmAction('Remove this local course?','This removes the course from this device. Export a copy first to keep your edits.',()=>{custom=custom.filter(c=>c.id!==b.dataset.id);persist(CUSTOM,custom);if(course.id===b.dataset.id){save();course=courses[0];loadProgress();persist('tara-selected',course.id);}render();}),
 'new-draft':()=>{if(read(DRAFT,null))confirmAction('Start a new draft?','This replaces the saved editor draft. Export it first if you want to keep it.',()=>newDraft());else newDraft();},
 'fork-draft':()=>{if(read(DRAFT,null))confirmAction('Edit this course?','This replaces the saved editor draft. Export it first if you want to keep it.',()=>newDraft(true));else newDraft(true);},
 'resume-draft':()=>{draft=read(DRAFT,null);nextRoute('editor');},
 'refresh-glosses':()=>{captureDraft();persist(DRAFT,draft);render();},
 'add-lesson':()=>{captureDraft();if(draft.lessons.length>=300){toast('A course can contain up to 300 lessons.');return;}draft.lessons.push(blankLesson());draftLessonIndex=draft.lessons.length-1;persist(DRAFT,draft);render();},
 'remove-lesson':b=>{captureDraft();draft.lessons.splice(Number(b.dataset.index),1);persist(DRAFT,draft);render();},
 'add-reading':b=>{captureDraft();draft.lessons[Number(b.dataset.index)].reading={title:'',text:'',translation:'',questions:[{prompt:'',options:['','',''],answer:0,explanation:''}]};persist(DRAFT,draft);render();},
 'remove-reading':b=>{captureDraft();delete draft.lessons[Number(b.dataset.index)].reading;persist(DRAFT,draft);render();},
 'add-question':b=>{captureDraft();const questions=draft.lessons[Number(b.dataset.index)].reading.questions;if(questions.length>=8){toast('Use up to eight comprehension questions.');return;}questions.push({prompt:'',options:['','',''],answer:0,explanation:''});persist(DRAFT,draft);render();},
 'remove-question':b=>{captureDraft();draft.lessons[Number(b.dataset.lesson)].reading.questions.splice(Number(b.dataset.index),1);persist(DRAFT,draft);render();},
 'add-task':b=>{captureDraft();draft.lessons[Number(b.dataset.index)].task={prompt:'',model:'',checklist:[]};persist(DRAFT,draft);render();},
 'remove-task':b=>{captureDraft();delete draft.lessons[Number(b.dataset.index)].task;persist(DRAFT,draft);render();},
 'add-entry':b=>{captureDraft();const l=draft.lessons[Number(b.dataset.index)];if(l.entries.length>=32){toast('A lesson can contain up to 32 entries.');return;}l.entries.push(blankEntry());persist(DRAFT,draft);render();},
 'remove-entry':b=>{captureDraft();draft.lessons[Number(b.dataset.lesson)].entries.splice(Number(b.dataset.index),1);persist(DRAFT,draft);render();},
 'export-draft':()=>{const value=validDraft();if(value)download(`${value.id}.json`,value);},
 'try-draft':()=>{const value=validDraft();if(value){confirmAction('Try this draft?', 'Save this course locally. This replaces a previous local course with the same id; shared courses are kept.',()=>addCourse(value));}},
 propose
};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled){e.preventDefault();try{actions[b.dataset.action]?.(b);}catch(err){console.error(err);toast('Something went wrong. Your saved progress is still available.');}}});
document.addEventListener('keydown',e=>{if(!session||e.ctrlKey||e.metaKey||e.altKey||$('#dialog').open||e.target.matches('textarea'))return;if(e.key==='Enter'&&(!e.target.matches('button'))){e.preventDefault();if(session.phase==='learn')actions['learn-next']();else if(session.phase==='reading')actions['reading-next']();else if(session.phase==='exercise'){if(session.checked)actions['exercise-next']();else if(!$('#check-answer')?.disabled)checkAnswer();}}if(session.phase==='exercise'&&!session.checked&&['choice','comprehension'].includes(session.queue[session.index].type)&&/^[1-4]$/.test(e.key)){const option=session.options[Number(e.key)-1];if(option){session.selected=option.id;renderSession();}}});
window.addEventListener('hashchange',()=>{speech.stop();render();window.scrollTo(0,0);});
async function boot(){try{
 const registry=await fetch('./courses/index.json').then(r=>{if(!r.ok)throw new Error('Course list is unavailable.');return r.json();});
 courses=await Promise.all(registry.map(async x=>{if(!/^[a-z0-9-]+\.json$/.test(x.file))throw new Error('Invalid course path.');const response=await fetch('./courses/'+x.file);if(!response.ok)throw new Error('Course unavailable.');const value=await response.json();const errors=validateCourse(value);if(errors.length)throw new Error(errors[0]);return value;}));
 if(!courses.length)throw new Error('No course is available.');
 custom=read(CUSTOM,[]);if(!Array.isArray(custom))custom=[];custom=custom.filter(c=>!validateCourse(c).length&&!courses.some(x=>x.id===c.id)).map(c=>({...c,status:'draft',reviewers:[]}));
 course=[...courses,...custom].find(c=>c.id===read('tara-selected',null))||courses[0];
 loadProgress();
 render();
 if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js',{type:'module'}).then(async()=>{await navigator.serviceWorker.ready;if(!navigator.serviceWorker.controller)await new Promise(resolve=>navigator.serviceWorker.addEventListener('controllerchange',resolve,{once:true}));workerReady=true;if(route==='downloads')refreshDownloads();}).catch(()=>{workerFailed=true;if(route==='downloads')renderDownloadList();});
 }catch(e){$('#app').innerHTML=`<main class="boot"><span class="brand">tara<span>!</span></span><h1 style="margin-top:30px">Let’s get you connected.</h1><p>${esc(e.message)} Check your connection and reload.</p><button class="btn" id="reload">Try again</button></main>`;$('#reload').onclick=()=>location.reload();}}
document.addEventListener('visibilitychange',()=>{if(document.hidden)speech.stop();});
boot();
